import type { CalendarImpactItem, ProjectRuntimeSettings, UserSession } from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';

type SettingTabId = 'calendar' | 'energy_weather' | 'guardrails' | 'notifications';
type SettingRuleItem = ProjectRuntimeSettings['rules'][number];

interface NotifyRouteRule {
  id: string;
  groupName: string;
  scope: string;
  severity: string;
  channels: string;
  enabled: boolean;
}

interface SpecialDateItem {
  id: string;
  date: string;
  label: string;
  mode: string;
}

function renderRuleRows(rules: SettingRuleItem[], canEdit: boolean): string {
  if (rules.length === 0) {
    return `<div class="lov-empty-state"><strong>暂无关联策略项</strong><span>当前分类下尚未绑定后台规则。</span></div>`;
  }
  return rules
    .map(
      (r) => `
      <div class="lov-setting-row">
        <div class="lov-setting-meta">
          <span class="lov-setting-title">
            <span>${r.name}</span>
            <span class="pacom-badge pacom-badge--neutral">v${r.version}</span>
            <span class="pacom-badge pacom-badge--accent">${r.scopeLabel}</span>
          </span>
          <span class="lov-setting-desc">${r.summary} · 回执：${r.receiptSummary ?? '已同步'}</span>
        </div>
        <div class="lov-setting-control">
          <span class="pacom-row-sub">${r.enabled ? '已启用' : '已停用'}</span>
          <button
            type="button"
            class="lov-switch"
            role="switch"
            aria-checked="${r.enabled ? 'true' : 'false'}"
            aria-label="切换 ${r.name}"
            data-toggle-rule="${r.id}"
            data-rule-ver="${r.version}"
            data-rule-next="${!r.enabled}"
            ${!canEdit ? 'disabled' : ''}
          >
            <span class="lov-switch-thumb"></span>
          </button>
        </div>
      </div>`
    )
    .join('');
}

