const TS_COLORS = ['#0088cc', '#2e9461', '#d97706', '#6d4aff', '#c2410c', '#202a44'];

function isAdditiveMetric(unit: string | undefined, label = ''): boolean {
  const u = (unit ?? '').trim().toLowerCase();
  if (!u) return false;
  if (u.includes('%') || u.includes('°c') || u.includes('ppm') || u.includes('ms') || u.includes('m²') || u.includes('/m2') || u.includes('db') || u.includes('lx')) {
    return false;
  }
  if (label.includes('率') || label.includes('均') || label.includes('强度') || label.includes('延迟')) {
    return false;
  }
  return true;
}

function scaleNumber(val: number, factor: number): number {
  const scaled = val * factor;
  return Math.abs(scaled) >= 10 ? Math.round(scaled) : Math.round(scaled * 10) / 10;
}

function formatKpiDisplay(rawVal: string, unit?: string): { value: string; unit: string; title: string } {
  const num = Number(String(rawVal).replaceAll(',', ''));
  const u = unit ?? '';
  if (!Number.isFinite(num)) return { value: rawVal, unit: u, title: `${rawVal} ${u}`.trim() };
  if (u === 'kWh' && Math.abs(num) >= 10000) {
    return {
      value: (num / 1000).toFixed(1),
      unit: 'MWh',
      title: `精确值：${num.toLocaleString('en-US')} kWh`,
    };
  }
  return {
    value: Number.isInteger(num) ? num.toLocaleString('en-US') : num.toLocaleString('en-US', { maximumFractionDigits: 1 }),
    unit: u,
    title: `${num.toLocaleString('en-US')} ${u}`.trim(),
  };
}

function buildScopedReport(base: AnalysisReport, factor: number): AnalysisReport {
  if (factor === 1) return base;
  const scaleSeries = isAdditiveMetric(base.unit);
  return {
    ...base,
    kpis: base.kpis.map((k) => {
      const num = Number(String(k.value).replaceAll(',', ''));
      if (!Number.isFinite(num) || !isAdditiveMetric(k.unit, k.label)) return k;
      return { ...k, value: String(scaleNumber(num, factor)) };
    }),
    series: scaleSeries
      ? base.series.map((pt) => ({
          ...pt,
          value: scaleNumber(pt.value, factor),
          ...(typeof pt.baseline === 'number' ? { baseline: scaleNumber(pt.baseline, factor) } : {}),
        }))
      : base.series,
    zoneBreakdown: base.zoneBreakdown.map((z) =>
      isAdditiveMetric(z.unit) ? { ...z, value: scaleNumber(z.value, factor) } : z
    ),
  };
}

function renderSvgChart(report: AnalysisReport, showEvents: boolean): string {
  const maxVal = Math.max(...report.series.map((s) => Math.max(s.value, s.baseline ?? 0)), 1);
  const barW = 46;
  const gap = 34;
  const padL = 36;
  const chartW = Math.max(report.series.length * (barW + gap) + padL * 2, 620);
  const chartH = 228;
  const baseY = 184;
  const plotH = 132;

  const gridLines = [0, 0.25, 0.5, 0.75, 1]
    .map((ratio) => {
      const y = Math.round(baseY - ratio * plotH);
      return `<line x1="${padL - 8}" y1="${y}" x2="${chartW - 18}" y2="${y}" stroke="oklch(85.12% 0 107 / 0.55)" stroke-dasharray="${ratio === 0 ? '0' : '3 3'}" />`;
    })
    .join('');

  const bars = report.series
    .map((pt, i) => {
      const x = padL + i * (barW + gap);
      const h = Math.max(8, Math.round((pt.value / maxVal) * plotH));
      const y = baseY - h;
      const isOverBaseline = typeof pt.baseline === 'number' && pt.value > pt.baseline * 1.08;
      const faultShade = isOverBaseline
        ? `<rect x="${x - 8}" y="34" width="${barW + 16}" height="${baseY - 34}" rx="8" fill="oklch(58.53% 0.2203 26.56 / 0.09)" />`
        : '';
      const baseLineMark =
        typeof pt.baseline === 'number'
          ? `<line x1="${x - 5}" y1="${Math.round(baseY - (pt.baseline / maxVal) * plotH)}" x2="${x + barW + 5}" y2="${Math.round(baseY - (pt.baseline / maxVal) * plotH)}" stroke="var(--pacom-brand)" stroke-width="1.5" stroke-dasharray="3 2" opacity="0.6" />`
          : '';
      const eventMarker =
        showEvents && (isOverBaseline || i === 1)
          ? `<g><title>${isOverBaseline ? '事件：告警触发 / 负荷超基线' : '事件：执行节能排程下发'}</title><circle cx="${x + barW / 2}" cy="18" r="7" fill="${isOverBaseline ? 'var(--pacom-status-warning)' : 'var(--pacom-accent-solid)'}" /><text x="${x + barW / 2}" y="21.5" text-anchor="middle" font-size="9" fill="#fff">${isOverBaseline ? '!' : '⚡'}</text></g>`
          : '';
      const labelNum = pt.value >= 10000 ? `${(pt.value / 1000).toFixed(1)}k` : pt.value.toLocaleString('en-US');
      return `
        ${faultShade}
        ${baseLineMark}
        ${eventMarker}
        <g>
          <title>${pt.label}：实测 ${pt.value.toLocaleString('en-US')} ${report.unit}${pt.baseline !== undefined ? ` / 基线 ${pt.baseline.toLocaleString('en-US')} ${report.unit}` : ''}</title>
          <rect x="${x}" y="${y}" width="${barW}" height="${h}" rx="7" fill="${isOverBaseline ? 'var(--pacom-status-warning)' : 'var(--pacom-accent-solid)'}" opacity="0.88" />
        </g>
        <text x="${x + barW / 2}" y="${y - 8}" text-anchor="middle" font-size="11" font-weight="500" fill="var(--pacom-text-primary)">${labelNum}</text>
        <text x="${x + barW / 2}" y="${baseY + 22}" text-anchor="middle" font-size="11" fill="var(--pacom-text-secondary)">${pt.label}</text>
      `;
    })
    .join('');

  return `
    <svg viewBox="0 0 ${chartW} ${chartH}" style="width:100%; height:232px; display:block;" role="img" aria-label="${report.category} 趋势图">
      ${gridLines}
      ${bars}
    </svg>
  `;
}

function getDeviceSeries(d: DeviceEntity): { unit: string; points: Array<number | null> } {
  if (d.connectivity === 'offline') {
    return { unit: '°C', points: [23.8, 24.0, 24.1, null, null, null, null, null] };
  }
  if (d.category === 'lighting') {
    const base = Number(d.telemetry.dimming?.value ?? 60);
    return { unit: '%', points: [0, 0, Math.round(base * 0.8), base, base, Math.round(base * 0.6), base, Math.round(base * 0.9)] };
  }
  if (d.category === 'hvac') {
    const sp = Number(d.telemetry.setpoint?.value ?? 24);
    return { unit: '°C', points: [sp + 0.8, sp + 0.6, sp + 0.3, sp, sp - 0.2, sp + 0.1, sp + 0.2, sp] };
  }
  if (d.category === 'sensor') {
    const t = Number(d.telemetry.temp?.value ?? 23.4);
    return { unit: '°C', points: [t - 0.5, t - 0.3, t, t + 0.3, t + 0.5, t + 0.2, t + 0.1, t] };
  }
  return { unit: 'ms', points: [16, 18, 17, 19, 18, 17, 18, 18] };
}

function renderTimeSeriesSvg(selectedDevices: DeviceEntity[], mode: TsViewMode): string {
  const labels = ['00:00', '03:00', '06:00', '09:00', '12:00', '15:00', '18:00', '21:00'];
  if (!selectedDevices.length) {
    return `<div class="lov-empty-state"><strong>尚未勾选设备测点</strong><span>请在左侧勾选 1 台或多台设备以开始多点时序对比。</span></div>`;
  }

  const renderLane = (laneDevices: DeviceEntity[], laneTitle: string): string => {
    const w = 680;
    const h = 158;
    const padL = 42;
    const padR = 18;
    const padT = 26;
    const padB = 26;
    const plotW = w - padL - padR;
    const plotH = h - padT - padB;

    const allVals: number[] = [];
    for (const d of laneDevices) {
      for (const v of getDeviceSeries(d).points) {
        if (typeof v === 'number') allVals.push(v);
      }
    }
    const minV = allVals.length ? Math.min(...allVals) * 0.92 : 0;
    const maxV = allVals.length ? Math.max(...allVals) * 1.08 : 100;
    const span = Math.max(maxV - minV, 1);

    const grid = [0, 0.5, 1]
      .map((r) => {
        const y = Math.round(padT + plotH * (1 - r));
        const val = (minV + span * r).toFixed(span < 15 ? 1 : 0);
        return `
          <line x1="${padL}" y1="${y}" x2="${w - padR}" y2="${y}" stroke="oklch(85.12% 0 107 / 0.5)" stroke-dasharray="${r === 0 ? '0' : '3 3'}" />
          <text x="${padL - 6}" y="${y + 3}" text-anchor="end" font-size="10" fill="var(--pacom-text-secondary)">${val}</text>
        `;
      })
      .join('');

    const xTicks = labels
      .map((lb, idx) => {
        const x = padL + (idx / (labels.length - 1)) * plotW;
        return `<text x="${x}" y="${h - 6}" text-anchor="middle" font-size="10" fill="var(--pacom-text-secondary)">${lb}</text>`;
      })
      .join('');

    const lines = laneDevices
      .map((d, idx) => {
        const color = TS_COLORS[idx % TS_COLORS.length]!;
        const pts = getDeviceSeries(d).points;
        const validCoords: string[] = [];
        let lastValidX = padL;
        let lastValidY = padT + plotH / 2;
        let hasGap = false;
        pts.forEach((v, i) => {
          const x = padL + (i / (pts.length - 1)) * plotW;
          if (typeof v === 'number') {
            const y = padT + plotH * (1 - (v - minV) / span);
            validCoords.push(`${x.toFixed(1)},${y.toFixed(1)}`);
            lastValidX = x;
            lastValidY = y;
          } else {
            hasGap = true;
          }
        });
        return `
          ${validCoords.length ? `<polyline fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" points="${validCoords.join(' ')}" />` : ''}
          ${hasGap ? `<line x1="${lastValidX.toFixed(1)}" y1="${lastValidY.toFixed(1)}" x2="${w - padR}" y2="${lastValidY.toFixed(1)}" stroke="var(--pacom-status-offline)" stroke-width="1.6" stroke-dasharray="4 4" /><text x="${w - padR - 4}" y="${lastValidY - 6}" text-anchor="end" font-size="10" fill="var(--pacom-status-warning)">No Data（断流离线）</text>` : ''}
        `;
      })
      .join('');

    const eventBadges = `
      <g><title>09:00 自动执行早间预冷排程</title><circle cx="${padL + (3 / 7) * plotW}" cy="12" r="6" fill="var(--pacom-accent-solid)" /><text x="${padL + (3 / 7) * plotW}" y="15" text-anchor="middle" font-size="8" fill="#fff">⚡</text></g>
      <g><title>15:00 VAV-02 通信离线告警</title><circle cx="${padL + (5 / 7) * plotW}" cy="12" r="6" fill="var(--pacom-status-warning)" /><text x="${padL + (5 / 7) * plotW}" y="15" text-anchor="middle" font-size="8" fill="#fff">!</text></g>
    `;

    return `
      <div class="pacom-card" style="padding:14px 16px; gap:8px;">
        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;">
          <strong style="font-size:13px; font-weight:500;">${laneTitle}</strong>
          <div style="display:flex; gap:10px; flex-wrap:wrap; font-size:12px;">
            ${laneDevices
              .map((d, idx) => `<span style="display:inline-flex; align-items:center; gap:5px;"><span style="width:8px; height:8px; border-radius:50%; background:${TS_COLORS[idx % TS_COLORS.length]};"></span>${d.name}</span>`)
              .join('')}
          </div>
        </div>
        <svg viewBox="0 0 ${w} ${h}" style="width:100%; height:158px; display:block;">
          ${grid}
          ${xTicks}
          ${eventBadges}
          ${lines}
        </svg>
      </div>
    `;
  };

  if (mode === 'shared') {
    return renderLane(selectedDevices, '单图叠合对比（Shared）');
  }

  const byUnit = new Map<string, DeviceEntity[]>();
  for (const d of selectedDevices) {
    const u = getDeviceSeries(d).unit;
    const list = byUnit.get(u) ?? [];
    list.push(d);
    byUnit.set(u, list);
  }
  return Array.from(byUnit.entries())
    .map(([unit, devs]) => renderLane(devs, `按单位分组泳道（${unit}）`))
    .join('');
}

function downloadReportCsv(report: AnalysisReport): void {
  const lines = [
    ['时段', `数值 (${report.unit})`, `基线 (${report.unit})`].join(','),
    ...report.series.map((s) => [s.label, String(s.value), s.baseline !== undefined ? String(s.baseline) : ''].join(',')),
  ];
  const blob = new Blob([`\uFEFF${lines.join('\n')}`], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `pacom-${report.category}-${report.range}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

function downloadTimeSeriesCsv(selectedDevices: DeviceEntity[]): void {
  const labels = ['00:00', '03:00', '06:00', '09:00', '12:00', '15:00', '18:00', '21:00'];
  const header = ['时间', ...selectedDevices.map((d) => `${d.name}(${getDeviceSeries(d).unit})`)].join(',');
  const rows = labels.map((lb, idx) =>
    [lb, ...selectedDevices.map((d) => String(getDeviceSeries(d).points[idx] ?? 'No Data'))].join(',')
  );
  const blob = new Blob([`\uFEFF${[header, ...rows].join('\n')}`], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'pacom-timeseries-export.csv';
  a.click();
  URL.revokeObjectURL(url);
}

export async function mountAnalysisView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  _session: UserSession
): Promise<void> {
  const hashQuery = new URLSearchParams(window.location.hash.split('?')[1] ?? '');
  const initTab = hashQuery.get('tab');
  const initCat = hashQuery.get('cat') as AnalysisCategory | null;
  const initDevice = hashQuery.get('device');

  let activeTab: AnalysisTab =
    initTab === 'timeseries'
      ? 'timeseries'
      : initCat && CATEGORY_META.some((c) => c.id === initCat)
        ? initCat
        : 'energy';
  let range: AnalysisRange | 'custom' = '7d';
  let customStart = '2026-11-16';
  let customEnd = '2026-11-23';
  let scopeId: string = E7F_IDS.floorId;
  let chartMode: 'chart' | 'table' = 'chart';
  let showEvents = true;
  let energyRightMode: 'breakdown' | 'load' = 'breakdown';
  let showCanvas = false;
  let report: AnalysisReport | null = null;
  let devices: DeviceEntity[] = await adapter.getFloorDevices(E7F_IDS.floorId).catch(() => []);

  let tsMode: TsViewMode = 'grouped';
  let tsInterval: TsInterval = '1h';
  const tsSelectedIds = new Set<string>(
    initDevice && devices.some((d) => d.id === initDevice)
      ? [initDevice]
      : devices.slice(0, 3).map((d) => d.id)
  );
  const favorites: TsFavorite[] = [
    {
      id: 'fav-hvac',
      name: 'E7F 空调供回温与离线对照',
      deviceIds: devices.filter((d) => d.category === 'hvac' || d.category === 'sensor').map((d) => d.id),
      mode: 'grouped',
      interval: '1h',
    },
    {
      id: 'fav-light',
      name: '照明回路亮度趋势对比',
      deviceIds: devices.filter((d) => d.category === 'lighting').map((d) => d.id),
      mode: 'shared',
      interval: '15m',
    },
  ];
  let tsNotice = '';

  async function load(): Promise<void> {
    const cat: AnalysisCategory = activeTab === 'timeseries' ? 'energy' : activeTab;
    const reqRange: AnalysisRange = range === 'custom' ? '30d' : range;
    report = await adapter.getAnalysisReport(cat, reqRange, E7F_IDS.floorId);
    render();
  }

  function render(): void {
    if (!report) return;
    const isTs = activeTab === 'timeseries';
    const currentCat: AnalysisCategory = activeTab === 'timeseries' ? 'energy' : activeTab;
    const activeCat = CATEGORY_META.find((c) => c.id === currentCat) ?? CATEGORY_META[0];
    const activeScope = SCOPE_OPTIONS.find((s) => s.id === scopeId) ?? SCOPE_OPTIONS[0]!;
    const scopedReport = buildScopedReport(report, activeScope.factor);
    const warningZones = scopedReport.zoneBreakdown.filter((z) => z.status === 'warning');
    const breakdown = BREAKDOWN_BY_CATEGORY[currentCat];
    const maxZoneVal = Math.max(...scopedReport.zoneBreakdown.map((z) => z.value), 1);
    const selectedTsDevices = devices.filter((d) => tsSelectedIds.has(d.id));

    root.innerHTML = `
      <div class="pacom-shell">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <div style="display:flex; align-items:center; gap:10px; min-width:0;">
              <h1 class="pacom-title" style="flex-shrink:0;">数据分析</h1>
              <div class="pacom-tabs" role="tablist" aria-label="分析维度">
                ${CATEGORY_META.map(
                  (c) => `<button class="pacom-tab" role="tab" aria-selected="${activeTab === c.id}" data-cat="${c.id}">${c.label}</button>`
                ).join('')}
                <button class="pacom-tab" role="tab" aria-selected="${activeTab === 'timeseries'}" data-cat="timeseries">多点时序</button>
              </div>
            </div>
            <div class="pacom-header-meta" style="flex-wrap:nowrap; flex-shrink:0;">
              <div class="pacom-scope-pill" style="width:196px;" title="切换统计空间范围">
                <select name="analysisScope" data-scope-select aria-label="选择统计空间范围">
                  ${SCOPE_OPTIONS.map((s) => `<option value="${s.id}" ${s.id === scopeId ? 'selected' : ''}>${s.label}</option>`).join('')}
                </select>
                <span class="pacom-scope-chevron">▾</span>
              </div>
              <select class="pacom-select" name="analysisRange" data-range-select aria-label="选择时间范围" style="height:32px;">
                <option value="today" ${range === 'today' ? 'selected' : ''}>今日</option>
                <option value="7d" ${range === '7d' ? 'selected' : ''}>近 7 天</option>
                <option value="30d" ${range === '30d' ? 'selected' : ''}>近 30 天</option>
                <option value="custom" ${range === 'custom' ? 'selected' : ''}>自定义范围</option>
              </select>
              <button class="pacom-btn" data-export-csv="1">导出 CSV</button>
              ${!isTs ? `<button class="pacom-btn ${showCanvas ? 'pacom-btn--primary' : ''}" data-toggle-canvas="1">${showCanvas ? '关闭对照' : '空间对照'}</button>` : ''}
            </div>
          </div>
          ${
            range === 'custom'
              ? `
              <div class="pacom-header-toolbar" style="justify-content:flex-end;">
                <div style="display:inline-flex; align-items:center; gap:8px; font-size:12px;">
                  <span class="pacom-row-sub">自定义统计区间（最长支持 371 天）：</span>
                  <input class="pacom-input" name="customStart" type="date" style="width:136px; height:28px;" value="${customStart}" data-custom-start />
                  <span class="pacom-row-sub">至</span>
                  <input class="pacom-input" name="customEnd" type="date" style="width:136px; height:28px;" value="${customEnd}" data-custom-end />
                </div>
              </div>`
              : ''
          }
        </header>

        ${
          isTs
            ? `
            <div class="lov-subnav-layout" style="padding:2px 4px 4px;">
              <aside class="pacom-left-pane" style="--pacom-sidebar-width:264px; min-width:240px;">
                <div class="pacom-pane-toolbar">
                  <div style="display:flex; justify-content:space-between; align-items:center;">
                    <span style="font-weight:500;">多点时序测点树</span>
                    <span class="pacom-row-sub">已选 ${selectedTsDevices.length}</span>
                  </div>
                  <div style="display:flex; flex-direction:column; gap:4px;">
                    <span class="pacom-row-sub">常用收藏视图</span>
                    ${favorites
                      .map(
                        (f) => `<button type="button" class="pacom-btn" style="height:28px; justify-content:flex-start; font-size:12px;" data-load-fav="${f.id}">★ ${f.name}</button>`
                      )
                      .join('')}
                    <button type="button" class="pacom-btn pacom-btn--ghost" style="height:26px; font-size:12px;" data-save-fav="1">+ 保存当前为收藏</button>
                  </div>
                </div>
                <div class="pacom-list">
                  ${devices
                    .map((d, idx) => {
                      const checked = tsSelectedIds.has(d.id);
                      const s = getDeviceSeries(d);
                      return `
                        <label class="pacom-row" style="cursor:pointer;">
                          <div style="display:flex; align-items:center; gap:8px; min-width:0;">
                            <input type="checkbox" data-ts-dev="${d.id}" ${checked ? 'checked' : ''} />
                            <span style="width:8px; height:8px; border-radius:50%; background:${TS_COLORS[idx % TS_COLORS.length]}; flex-shrink:0;"></span>
                            <div style="min-width:0;">
                              <div class="pacom-row-title" style="font-size:13px;">${d.name}</div>
                              <div class="pacom-row-sub">${s.unit} · ${d.connectivity === 'online' ? '在线上报' : '断流离线'}</div>
                            </div>
                          </div>
                        </label>`;
                    })
                    .join('')}
                </div>
              </aside>
              <div class="lov-subnav-main" style="padding:2px 4px 24px;">
                ${tsNotice ? `<div class="lov-banner lov-banner--ok"><span class="lov-banner-title">${tsNotice}</span></div>` : ''}
                <div class="lov-section-head">
                  <div style="display:flex; align-items:center; gap:10px; flex-wrap:wrap;">
                    <h2 class="lov-section-title">多设备实时遥测对比（Time Series）</h2>
                    <span class="pacom-row-sub">⚡ 控制排程 · ! 告警触发 · 虚线为 No Data 断流</span>
                  </div>
                  <div style="display:flex; align-items:center; gap:8px;">
                    <select class="pacom-select" name="tsInterval" data-ts-interval aria-label="采样粒度" style="height:28px; font-size:12px;">
                      <option value="15m" ${tsInterval === '15m' ? 'selected' : ''}>15 分钟</option>
                      <option value="1h" ${tsInterval === '1h' ? 'selected' : ''}>1 小时</option>
                      <option value="1d" ${tsInterval === '1d' ? 'selected' : ''}>1 天</option>
                    </select>
                    <div class="pacom-tabs">
                      <button class="pacom-tab" aria-selected="${tsMode === 'grouped'}" data-ts-mode="grouped">按单位分组</button>
                      <button class="pacom-tab" aria-selected="${tsMode === 'shared'}" data-ts-mode="shared">单图叠合</button>
                    </div>
                  </div>
                </div>
                ${renderTimeSeriesSvg(selectedTsDevices, tsMode)}
              </div>
            </div>`
            : `
            <div class="pacom-content-page" style="padding:6px 4px 28px;">
              <div class="lov-kpi-strip" role="region" aria-label="核心统计指标">
                ${scopedReport.kpis
                  .map((k) => {
                    const fmt = formatKpiDisplay(k.value, k.unit);
                    return `
                      <div class="lov-kpi-cell" title="${fmt.title}">
                        <span class="lov-kpi-label">${k.label}</span>
                        <div class="lov-kpi-value">
                          <span>${fmt.value}</span>
                          ${fmt.unit ? `<span class="lov-kpi-unit">${fmt.unit}</span>` : ''}
                        </div>
                        <span class="lov-kpi-delta">${k.delta ?? '与基线持平'}</span>
                      </div>`;
                  })
                  .join('')}
              </div>

              <section class="lov-section">
                <div class="lov-section-head">
                  <div style="display:flex; align-items:center; gap:10px; flex-wrap:wrap;">
                    <h2 class="lov-section-title">${activeCat?.label ?? '趋势'}趋势（${scopedReport.unit}）</h2>
                    <span class="pacom-badge pacom-badge--online">数据完整度 99.4%</span>
                    <span class="pacom-row-sub">口径：${activeScope.label} · 更新于 ${scopedReport.updatedAt.slice(5, 16).replace('T', ' ')}</span>
                  </div>
                  <div style="display:flex; align-items:center; gap:10px; flex-wrap:wrap;">
                    <label style="display:inline-flex; align-items:center; gap:6px; font-size:12px; color:var(--pacom-text-secondary); cursor:pointer;">
                      <span>叠加事件标记</span>
                      <button type="button" class="lov-switch" role="switch" aria-checked="${showEvents}" data-toggle-events="1" aria-label="叠加告警与指令事件标记">
                        <span class="lov-switch-thumb"></span>
                      </button>
                    </label>
                    <div class="pacom-tabs">
                      <button class="pacom-tab" aria-selected="${chartMode === 'chart'}" data-chart-mode="chart">趋势图</button>
                      <button class="pacom-tab" aria-selected="${chartMode === 'table'}" data-chart-mode="table">明细原表</button>
                    </div>
                  </div>
                </div>

                <div class="pacom-card" style="gap:16px;">
                  ${
                    chartMode === 'chart'
                      ? renderSvgChart(scopedReport, showEvents)
                      : `
                      <div class="lov-table-wrap">
                        <table class="lov-table">
                          <thead>
                            <tr>
                              <th>统计时段</th>
                              <th>实测值（${scopedReport.unit}）</th>
                              <th>基线参考</th>
                              <th>状态</th>
                            </tr>
                          </thead>
                          <tbody>
                            ${scopedReport.series
                              .map((s) => {
                                const over = typeof s.baseline === 'number' && s.value > s.baseline * 1.08;
                                return `
                                  <tr>
                                    <td><strong>${s.label}</strong></td>
                                    <td>${s.value.toLocaleString('en-US')}</td>
                                    <td>${s.baseline !== undefined ? s.baseline.toLocaleString('en-US') : '-'}</td>
                                    <td><span class="pacom-badge ${over ? 'pacom-badge--warning' : 'pacom-badge--online'}">${over ? '超基线' : '正常'}</span></td>
                                  </tr>`;
                              })
                              .join('')}
                          </tbody>
                        </table>
                      </div>`
                  }
                  <div class="lov-banner">
                    <div class="lov-banner-text">
                      <span class="lov-banner-title">${activeCat?.desc ?? '空间运行洞察'}</span>
                      <span class="lov-banner-sub">
                        ${
                          warningZones.length > 0
                            ? `当前有 ${warningZones.length} 个功能区指标偏高（${warningZones.map((z) => z.zoneName).join('、')}），建议前往智能策略优化启停时段。`
                            : breakdown.summary
                        }
                      </span>
                    </div>
                    <button class="pacom-btn" data-go-strategy="1">去智能策略优化 →</button>
                  </div>
                </div>
              </section>

              <div class="lov-grid-2">
                <section class="lov-section">
                  <div class="lov-section-head">
                    <h2 class="lov-section-title">功能区排行对比</h2>
                    <span class="pacom-row-sub">${scopedReport.zoneBreakdown.length} 个功能区</span>
                  </div>
                  <div class="lov-table-card">
                    <div class="lov-table-wrap">
                      <table class="lov-table">
                        <thead>
                          <tr>
                            <th>功能区</th>
                            <th>占比分布</th>
                            <th>当前值</th>
                            <th>状态</th>
                          </tr>
                        </thead>
                        <tbody>
                          ${scopedReport.zoneBreakdown
                            .map((z) => {
                              const barPct = Math.max(8, Math.round((z.value / maxZoneVal) * 100));
                              return `
                                <tr>
                                  <td style="font-weight:500;">${z.zoneName.replace(/^7F\s*/, '')}</td>
                                  <td style="width:140px;">
                                    <div style="height:6px; border-radius:999px; background:var(--pacom-surface-recessed); overflow:hidden;">
                                      <div style="width:${barPct}%; height:100%; border-radius:999px; background:${z.status === 'warning' ? 'var(--pacom-status-warning)' : 'var(--pacom-accent-solid)'};"></div>
                                    </div>
                                  </td>
                                  <td><strong>${z.value.toLocaleString('en-US')}</strong> <span class="pacom-row-sub">${z.unit}</span></td>
                                  <td>
                                    <span class="pacom-badge ${z.status === 'warning' ? 'pacom-badge--warning' : 'pacom-badge--online'}">
                                      ${z.status === 'warning' ? '偏高关注' : '正常'}
                                    </span>
                                  </td>
                                </tr>`;
                            })
                            .join('')}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </section>

                <section class="lov-section">
                  <div class="lov-section-head">
                    <h2 class="lov-section-title">${showCanvas ? 'E7F 空间对照预览' : currentCat === 'energy' && energyRightMode === 'load' ? '峰谷负荷分布（Load Profile）' : breakdown.title}</h2>
                    ${
                      !showCanvas && currentCat === 'energy'
                        ? `
                        <div class="pacom-tabs">
                          <button class="pacom-tab" aria-selected="${energyRightMode === 'breakdown'}" data-energy-right="breakdown">分项构成</button>
                          <button class="pacom-tab" aria-selected="${energyRightMode === 'load'}" data-energy-right="load">峰谷负荷</button>
                        </div>`
                        : `<span class="pacom-row-sub">${showCanvas ? '与空间总览状态独立' : '当前周期结构占比'}</span>`
                    }
                  </div>
                  <div class="pacom-card" style="flex:1; justify-content:center; gap:14px;">
                    ${
                      showCanvas
                        ? `<img class="pacom-plan-img" src="./media/7F.webp" alt="E7F 分析楼层预览" style="max-height:240px; margin:0 auto;" />`
                        : `
                        ${
                          currentCat === 'environment'
                            ? `
                            <div style="display:flex; flex-direction:column; gap:6px; padding-bottom:8px; border-bottom:var(--hw) solid var(--pacom-border-subtle);">
                              <div style="display:flex; justify-content:space-between; font-size:12px;">
                                <span style="font-weight:500;">ASHRAE 舒适带时长分布</span>
                                <span class="pacom-row-sub">过冷 1.6% · 舒适 96.2% · 过热 2.2%</span>
                              </div>
                              <div style="display:flex; height:10px; border-radius:999px; overflow:hidden; gap:2px;">
                                <div style="width:4%; background:var(--pacom-accent-solid);" title="过冷 1.6%"></div>
                                <div style="width:91%; background:var(--pacom-status-online);" title="舒适达标 96.2%"></div>
                                <div style="width:5%; background:var(--pacom-status-warning);" title="过热 2.2%"></div>
                              </div>
                            </div>`
                            : ''
                        }
                        ${(currentCat === 'energy' && energyRightMode === 'load' ? PEAK_LOAD_ITEMS : breakdown.items)
                          .map(
                            (item) => `
                            <div style="display:flex; flex-direction:column; gap:6px;">
                              <div style="display:flex; justify-content:space-between; align-items:center; font-size:13px;">
                                <span style="font-weight:500; color:var(--pacom-text-primary);">${item.name}</span>
                                <span class="pacom-row-sub">${item.detail} · <strong style="color:var(--pacom-text-primary);">${item.pct}%</strong></span>
                              </div>
                              <div style="height:7px; border-radius:999px; background:var(--pacom-surface-recessed); overflow:hidden;">
                                <div style="width:${Math.min(100, item.pct)}%; height:100%; border-radius:999px; background:${item.color};"></div>
                              </div>
                            </div>`
                          )
                          .join('')}`
                    }
                  </div>
                </section>
              </div>
            </div>`
        }
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-cat]').forEach((btn) => {
      btn.addEventListener('click', () => {
        activeTab = (btn.dataset.cat as AnalysisTab) ?? 'energy';
        tsNotice = '';
        if (activeTab === 'timeseries') render();
        else void load();
      });
    });

    root.querySelector<HTMLSelectElement>('[data-scope-select]')?.addEventListener('change', (e) => {
      scopeId = (e.currentTarget as HTMLSelectElement).value;
      render();
    });

    root.querySelector<HTMLSelectElement>('[data-range-select]')?.addEventListener('change', (e) => {
      range = ((e.currentTarget as HTMLSelectElement).value as AnalysisRange | 'custom') ?? '7d';
      void load();
    });

    root.querySelector<HTMLInputElement>('[data-custom-start]')?.addEventListener('change', (e) => {
      customStart = (e.currentTarget as HTMLInputElement).value;
    });
    root.querySelector<HTMLInputElement>('[data-custom-end]')?.addEventListener('change', (e) => {
      customEnd = (e.currentTarget as HTMLInputElement).value;
    });

    root.querySelectorAll<HTMLButtonElement>('[data-chart-mode]').forEach((btn) => {
      btn.addEventListener('click', () => {
        chartMode = (btn.dataset.chartMode as 'chart' | 'table') ?? 'chart';
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-toggle-events]')?.addEventListener('click', () => {
      showEvents = !showEvents;
      render();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-energy-right]').forEach((btn) => {
      btn.addEventListener('click', () => {
        energyRightMode = (btn.dataset.energyRight as 'breakdown' | 'load') ?? 'breakdown';
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-export-csv]')?.addEventListener('click', () => {
      if (isTs) downloadTimeSeriesCsv(selectedTsDevices);
      else downloadReportCsv(scopedReport);
    });

    root.querySelector<HTMLButtonElement>('[data-toggle-canvas]')?.addEventListener('click', () => {
      showCanvas = !showCanvas;
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-go-strategy]')?.addEventListener('click', () => {
      window.location.hash = '#scenes';
    });

    root.querySelectorAll<HTMLInputElement>('[data-ts-dev]').forEach((chk) => {
      chk.addEventListener('change', () => {
        const id = chk.dataset.tsDev;
        if (!id) return;
        if (chk.checked) tsSelectedIds.add(id);
        else tsSelectedIds.delete(id);
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-ts-mode]').forEach((btn) => {
      btn.addEventListener('click', () => {
        tsMode = (btn.dataset.tsMode as TsViewMode) ?? 'grouped';
        render();
      });
    });

    root.querySelector<HTMLSelectElement>('[data-ts-interval]')?.addEventListener('change', (e) => {
      tsInterval = ((e.currentTarget as HTMLSelectElement).value as TsInterval) ?? '1h';
      render();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-load-fav]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const fav = favorites.find((f) => f.id === btn.dataset.loadFav);
        if (!fav) return;
        tsSelectedIds.clear();
        fav.deviceIds.forEach((id) => tsSelectedIds.add(id));
        tsMode = fav.mode;
        tsInterval = fav.interval;
        tsNotice = `已加载收藏视图「${fav.name}」。`;
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-save-fav]')?.addEventListener('click', () => {
      if (tsSelectedIds.size === 0) return;
      const name = `自定义对比 #${favorites.length + 1}（${tsSelectedIds.size} 台）`;
      favorites.push({
        id: `fav-${Date.now()}`,
        name,
        deviceIds: Array.from(tsSelectedIds),
        mode: tsMode,
        interval: tsInterval,
      });
      tsNotice = `已保存当前时序配置为「${name}」。`;
      render();
    });
  }

  await load();
}
